import { join } from "node:path";
import { sha256 } from "./private.mjs";
import {
  readTestJudgment,
  testJudgmentToolSchema,
} from "./execution-status.mjs";

/** Project the existing redacted Runner row. Do not copy input text or keys. */
export function projectCaseAction(row) {
  const action = {
    index: row.index,
    type: row.action.type,
    status: row.status,
    startedAt: row.startedAt,
    endedAt: row.endedAt,
  };
  const operation = row.operation;
  if (
    operation?.kind === "browser-refresh" &&
    operation.method === "page.reload"
  ) {
    // These fields already pass through Runner redaction. Keep this list narrow
    // so new operation fields do not silently expand the case evidence surface.
    action.operation = Object.fromEntries(
      [
        "kind",
        "method",
        "pageId",
        "urlBefore",
        "waitUntil",
        "status",
        "dispatchedAt",
        "urlAfter",
        "completedAt",
        "error",
        "completion",
      ]
        .filter((key) => Object.hasOwn(operation, key))
        .map((key) => [key, operation[key]]),
    );
    if (Object.hasOwn(operation, "response"))
      action.operation.response = operation.response
        ? { url: operation.response.url, status: operation.response.status }
        : null;
  }
  return action;
}

/** Case boundaries are declared by Runner during execution, never inferred from
 * screenshots or retrofitted to old evidence. They are not test verdicts. */
// Keep prompts general. Only give interaction advice that applies across common tasks; keep case-specific steps in tests.
export function createCaseEvidence(
  planRef,
  {
    save,
    tracing,
    now = () => new Date().toISOString(),
    platform = "browser",
    onActiveChange,
    assess = false,
  },
) {
  const valid =
    planRef &&
    /^[a-f0-9]{64}$/.test(planRef.answerId) &&
    /^[a-f0-9]{64}$/.test(planRef.resultSha256) &&
    Array.isArray(planRef.selectedTestIds) &&
    planRef.selectedTestIds.length > 0 &&
    planRef.selectedTestIds.every(
      (id) => typeof id === "string" && id.trim() && id.length <= 512,
    ) &&
    new Set(planRef.selectedTestIds).size === planRef.selectedTestIds.length;
  const ids = valid ? [...planRef.selectedTestIds] : [];
  const record = {
    schema: "loki.runner.case-evidence/1",
    attribution: "runner-declared-boundaries",
    planRef: valid
      ? { answerId: planRef.answerId, resultSha256: planRef.resultSha256 }
      : null,
    selectedTestIds: ids,
    cases: [],
    unassignedActions: [],
    unassignedScreenshots: [],
  };
  let active = null;
  const recordsJudgments = assess && ids.length > 0;
  const judgments = new Map();
  let latestJudgment;
  const persist = () =>
    ids.length ? save("case-evidence.json", record) : Promise.resolve();
  const tools = ids.length
    ? [
        {
          type: "function",
          name: "test_case",
          strict: true,
          description: recordsJudgments
            ? "Start the selected test with judgment:null. After its last observation, end it with testId:null and the judgment for that test. Recording performs no application action."
            : "Record the current test case boundary. Record the boundary before its first action and after its last observation. This records grouping only; it does not run, retry, or verify a test. Use null to end the current case. Do not replay actions to create evidence.",
          parameters: {
            type: "object",
            additionalProperties: false,
            properties: {
              testId: {
                anyOf: [{ type: "string", enum: ids }, { type: "null" }],
              },
              ...(recordsJudgments
                ? {
                    judgment: {
                      anyOf: [testJudgmentToolSchema(), { type: "null" }],
                    },
                  }
                : {}),
            },
            required: recordsJudgments ? ["testId", "judgment"] : ["testId"],
          },
        },
      ]
    : [];
  async function end(state) {
    if (!active) return;
    active.state = state;
    active.endedAt = now();
    active = null;
    await tracing().groupEnd();
    await persist();
  }
  return {
    tools,
    recordsJudgments,
    hasUnfinishedJudgments: () =>
      recordsJudgments && ids.some((id) => !judgments.has(id)),
    assessment(snapshot) {
      if (!recordsJudgments || (!snapshot.executionReport && !latestJudgment))
        return snapshot;
      const report = snapshot.executionReport ?? {
        schema: "loki.runner.execution-report/2",
        status: "blocked",
        reason: "The Run ended before its final status report.",
        remainingSteps: [],
        evidence: [],
        questions: [],
        basis: "model-authored-unverified",
        responseId: latestJudgment.providerResponseId,
        callId: latestJudgment.callId,
      };
      return {
        ...snapshot,
        executionReport: { ...report, test_results: [...judgments.values()] },
      };
    },
    instruction: ids.length
      ? `Use test_case to group ${platform} actions for the selected test IDs: ${JSON.stringify(ids)}. Record each boundary before that case’s first action. End with testId:null after its final observation. Setup outside these boundaries stays at Run level.${recordsJudgments ? " Set judgment to null when starting a test. When ending the test, give its judgment from the observations already made. Record unfinished work as unfinished. Wait for the saved judgment before starting the next test. Use execution_status for the overall Run." : " Boundaries do not establish pass/fail or authorize retries."}`
      : "",
    async call(item, responseId, providerCall) {
      let output;
      try {
        const args = JSON.parse(item.arguments);
        if (
          !args ||
          Object.keys(args).length !== (recordsJudgments ? 2 : 1) ||
          !Object.hasOwn(args, "testId") ||
          (args.testId !== null && !ids.includes(args.testId))
        )
          throw Error("Select a supplied test ID or null.");
        if (args.testId !== null && active)
          throw Error("End the current case before selecting another case.");
        let queue;
        if (args.testId === null) {
          if (recordsJudgments) {
            if (!active) throw Error("There is no active test to judge.");
            const judgment = readTestJudgment(args.judgment, active.testId);
            const savedJudgment = {
              judgment,
              occurrence: active.occurrence,
              providerResponseId: responseId,
              providerCall,
              callId: item.call_id,
            };
            try {
              await save(
                `test-judgment-${record.cases.length}.json`,
                savedJudgment,
              );
            } catch {
              throw Error("The test judgment could not be saved.");
            }
            judgments.set(active.testId, judgment);
            latestJudgment = savedJudgment;
          }
          await end("ended");
          if (onActiveChange) {
            const notStartedTestIds = ids.filter(
              (id) => !record.cases.some((row) => row.testId === id),
            );
            if (onActiveChange(false, notStartedTestIds))
              queue = { remainingTestIds: [], notStartedTestIds };
          }
        } else {
          if (recordsJudgments && args.judgment !== null)
            throw Error("A test can be judged after its final observation.");
          const occurrence =
            record.cases.filter((c) => c.testId === args.testId).length + 1;
          const title = `Test case ${args.testId} · occurrence ${occurrence}`;
          onActiveChange?.(true);
          try {
            await tracing().group(title);
          } catch (error) {
            onActiveChange?.(false);
            throw error;
          }
          active = {
            testId: args.testId,
            occurrence,
            title,
            state: "recording",
            startedAt: now(),
            endedAt: null,
            actions: [],
            screenshots: [],
          };
          record.cases.push(active);
          await persist();
        }
        output = {
          recorded: true,
          ...queue,
          testId: active?.testId ?? null,
          occurrence: active?.occurrence ?? null,
        };
      } catch (error) {
        output = { recorded: false, error: String(error.message) };
      }
      return {
        type: "function_call_output",
        call_id: item.call_id,
        output: JSON.stringify(output),
      };
    },
    async action(row) {
      if (!ids.length) return;
      (active?.actions ?? record.unassignedActions).push(
        projectCaseAction(row),
      );
      await persist();
    },
    async screenshot(name, sha256) {
      if (!ids.length) return;
      // Reuse the screenshot the existing Runner path already saved. A provider
      // response can overwrite screen-N.png; retain only its final saved bytes.
      for (const entries of [
        record.unassignedScreenshots,
        ...record.cases.map((item) => item.screenshots),
      ]) {
        const old = entries.findIndex((item) => item.name === name);
        if (old !== -1) entries.splice(old, 1);
      }
      (active?.screenshots ?? record.unassignedScreenshots).push({
        name,
        sha256,
        capturedAt: now(),
      });
      await persist();
    },
    async close() {
      if (active) await end("interrupted");
      else await persist();
    },
  };
}

export function createRunEvidence(out, privateFile) {
  const saved = new Map(),
    savedOriginals = new Map();
  async function save(name, value) {
    const path = join(out, name);
    // Retain the exact bytes handed to the writer, including a copy of binary inputs.
    const bytes = Buffer.from(
      typeof value === "string" || Buffer.isBuffer(value)
        ? value
        : JSON.stringify(value, null, 2),
    );
    await privateFile(path, bytes);
    saved.set(name, { path: name, sha256: sha256(bytes), bytes: bytes.length });
    savedOriginals.set(name, bytes);
  }
  async function retainEvidence(names, providerCall) {
    const originals = names.flatMap((name) => {
      const record = saved.get(name),
        bytes = savedOriginals.get(name);
      return record && bytes ? [{ ...record, bytes }] : [];
    });
    const references = [];
    for (const [index, original] of originals.entries()) {
      const checkpointPath = `checkpoint-${providerCall}-${index}.bin`;
      await save(checkpointPath, original.bytes);
      references.push({
        path: original.path,
        sha256: original.sha256,
        bytes: original.bytes.length,
        checkpointPath,
      });
    }
    return references;
  }
  return { saved, save, retainEvidence };
}
